// Candidate-only native lossless transfer preflight. Private typed projections; no caller-authored serving authority.
use std::{collections::BTreeMap,ffi::{CStr,CString},fs::File,os::fd::AsRawFd,path::Path};
use anyhow::{anyhow,bail,ensure,Context};
use libsqlite3_sys as ffi;
use serde::Serialize;
use sha2::{Digest,Sha256};

#[derive(Debug,Clone,PartialEq,Eq,Serialize,serde::Deserialize)]
enum Cell { Null, Text(Vec<u8>), Integer(i64), Blob(Vec<u8>), Real(u64) }
#[derive(Debug,Clone,PartialEq,Eq,Serialize,serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct Column { name:String,kind:String,required:bool }
#[derive(Debug,Clone,PartialEq,Eq,Serialize,serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct Table {columns:Vec<Column>,keys:Vec<String>,rows:Vec<Vec<Cell>>}
struct NativeSnapshot<'a> {profile:EngineCatalogueProfile,bundle:&'a crate::storage::backup_inventory::ValidatedBundle,_database:File,tables:BTreeMap<String,Table>,schema_rows:Vec<Vec<Cell>>,raw_sqlite_migrations:Vec<Vec<Cell>>,reference_paths:Vec<String>}
#[derive(Debug,Serialize)]
struct PreflightCertificate {backup_id:String,manifest_sha256:String,sqlite_database_sha256:String,source_schema_sha256:String,target_schema_baseline_sha256:String,table_hashes:BTreeMap<String,(usize,String)>,source_migrations_sha256:String,checked_current_file_references:Vec<String>,serving_allowed:bool}
fn digest(raw:&[u8])->String{hex::encode(Sha256::digest(raw))}
fn name(s:&str)->anyhow::Result<String>{ensure!(!s.is_empty()&&s.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||b==b'_'),"Unsafe schema identifier");Ok(s.into())}
fn quoted(s:&str)->anyhow::Result<String>{Ok(format!("\"{}\"",name(s)?))}
fn shape()->anyhow::Result<BTreeMap<String,Table>> { shape_for_profile(EngineCatalogueProfile::CURRENT) }
fn shape_for_profile(profile:EngineCatalogueProfile)->anyhow::Result<BTreeMap<String,Table>> {
 let raw=concat!(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0001_current_schema.sql")), "\n", include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0003_attachment_upload_receipts.sql")));let current_ddl=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0004_immutable_attachment_versions.sql"));let raw=if profile!=EngineCatalogueProfile::Historical49Pg3 {format!("{raw}\n{current_ddl}")} else {raw.to_owned()};let raw=if profile.has_capacity() {format!("{raw}\n{}",include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0005_attachment_capacity_reservations.sql")))}else{raw};let raw=if !profile.retention_tables().is_empty(){format!("{raw}\n{}",include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0006_attachment_erasure_outbox.sql")))}else{raw};let raw=if profile.has_erasure(){format!("{raw}\n{}",include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0007_attachment_erasure_dispositions.sql")))}else{raw};let raw=if profile.has_publication(){format!("{raw}\n{}",include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0008_document_publication_history.sql")))}else{raw};let raw=if profile.has_audiences(){format!("{raw}\n{}",include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0009_draft_asset_audiences.sql")))}else{raw};let raw=if !profile.transfer_tables().is_empty(){format!("{raw}\n{}",include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0010_draft_transfer_receipts.sql")))}else{raw};let raw=if !profile.discussion_tables().is_empty(){format!("{raw}\n{}",include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0011_draft_discussions.sql")))}else{raw};let mut tables=BTreeMap::new();let mut current:Option<(String,Table)>=None;
 for line in raw.lines(){let line=line.trim();
  if let Some(rest)=line.strip_prefix("CREATE TABLE "){ensure!(current.is_none(),"Nested DDL");let n=name(rest.strip_suffix(" (").context("Unexpected table declaration")?)?;current=Some((n,Table{columns:vec![],keys:vec![],rows:vec![]}));continue;}
  let Some((_,t))=&mut current else{continue};
  if line==");"{let(n,mut t)=current.take().unwrap();for c in &mut t.columns{if t.keys.contains(&c.name){c.required=true;}}ensure!(!t.columns.is_empty()&&!t.keys.is_empty(),"Missing target keys");ensure!(tables.insert(n,t).is_none(),"Duplicate target table");continue;}
  if line.starts_with("PRIMARY KEY"){let inside=line.split_once('(').context("Malformed PK")?.1.split_once(')').context("Malformed PK")?.0;for key in inside.split(','){t.keys.push(name(key.trim())?);}continue;}
  let words:Vec<_>=line.split_whitespace().collect();if words.len()>=2&&matches!(words[1].trim_end_matches(','),"TEXT"|"BIGINT"|"BYTEA"){
   let n=name(words[0])?;if line.contains("PRIMARY KEY"){t.keys.push(n.clone());}t.columns.push(Column{name:n,kind:words[1].trim_end_matches(',').into(),required:line.contains("NOT NULL")||line.contains("PRIMARY KEY")});
  }else{ensure!(line.is_empty()||["CHECK","UNIQUE","FOREIGN","(","),","AND ","OR",")"].iter().any(|s|line.starts_with(s)),"Unknown target DDL line: {line}");}
 }
 ensure!(current.is_none()&&tables.len()==profile.application_tables(),"Unexpected target schema");Ok(tables)
}
struct NativeDb(*mut ffi::sqlite3);
impl Drop for NativeDb{fn drop(&mut self){if !self.0.is_null(){unsafe{ffi::sqlite3_close(self.0);}}}}
struct Statement(*mut ffi::sqlite3_stmt);
impl Drop for Statement{fn drop(&mut self){unsafe{ffi::sqlite3_finalize(self.0);}}}
impl NativeDb {
 fn close(mut self)->anyhow::Result<()>{let code=unsafe{ffi::sqlite3_close(self.0)};ensure!(code==ffi::SQLITE_OK,"Native source handle did not close");self.0=std::ptr::null_mut();Ok(())}

 fn open(file:&File)->anyhow::Result<Self>{let uri=CString::new(format!("file:/proc/self/fd/{}?mode=ro&immutable=1",file.as_raw_fd()))?;let mut p=std::ptr::null_mut();let rc=unsafe{ffi::sqlite3_open_v2(uri.as_ptr(),&mut p,ffi::SQLITE_OPEN_READONLY|ffi::SQLITE_OPEN_URI|ffi::SQLITE_OPEN_NOMUTEX,std::ptr::null())};if rc!=ffi::SQLITE_OK{if !p.is_null(){unsafe{ffi::sqlite3_close(p);}}bail!("Cannot open immutable native snapshot");}let db=Self(p);let main=CString::new("main")?;ensure!(unsafe{ffi::sqlite3_db_readonly(db.0,main.as_ptr())}==1,"Native snapshot not readonly");Ok(db)}
 fn rows(&self,sql:&str)->anyhow::Result<Vec<Vec<Cell>>>{let query=CString::new(sql)?;let mut p=std::ptr::null_mut();let mut tail=std::ptr::null();let rc=unsafe{ffi::sqlite3_prepare_v2(self.0,query.as_ptr(),-1,&mut p,&mut tail)};ensure!(rc==ffi::SQLITE_OK&&!p.is_null(),"Cannot prepare native snapshot query");let statement=Statement(p);ensure!(unsafe{CStr::from_ptr(tail)}.to_bytes().is_empty(),"Unexpected query tail");let mut rows=vec![];let mut bytes=0usize;
 loop{match unsafe{ffi::sqlite3_step(statement.0)}{ffi::SQLITE_DONE=>break,ffi::SQLITE_ROW=>{},_=>bail!("Native snapshot query failed")};let mut row=vec![];for i in 0..unsafe{ffi::sqlite3_column_count(statement.0)}{
  let cell=match unsafe{ffi::sqlite3_column_type(statement.0,i)}{ffi::SQLITE_NULL=>Cell::Null,ffi::SQLITE_INTEGER=>Cell::Integer(unsafe{ffi::sqlite3_column_int64(statement.0,i)}),ffi::SQLITE_FLOAT=>Cell::Real(unsafe{ffi::sqlite3_column_double(statement.0,i)}.to_bits()),kind @ (ffi::SQLITE_TEXT|ffi::SQLITE_BLOB)=>{
   // Observe original storage class BEFORE asking SQLite for a byte view.
   let ptr=unsafe{ffi::sqlite3_column_blob(statement.0,i)};let n=unsafe{ffi::sqlite3_column_bytes(statement.0,i)};ensure!(n>=0&&(n==0||!ptr.is_null()),"Invalid raw SQLite cell");ensure!(n as usize<=16*1024*1024,"Raw cell bound exceeded");let raw=if n==0{vec![]}else{unsafe{std::slice::from_raw_parts(ptr.cast::<u8>(),n as usize)}.to_vec()};bytes=bytes.checked_add(raw.len()).context("Row size overflow")?;if kind==ffi::SQLITE_TEXT{Cell::Text(raw)}else{Cell::Blob(raw)}},_=>bail!("Unknown SQLite storage class")};row.push(cell);
 }ensure!(rows.len()<100000&&bytes<=512*1024*1024,"Native candidate snapshot bound exceeded");rows.push(row);}
 Ok(rows)
 }
}
fn text(cell:&Cell)->anyhow::Result<&str>{if let Cell::Text(raw)=cell{std::str::from_utf8(raw).context("Invalid UTF8 metadata")}else{bail!("Expected text metadata")}}
fn validate_cell(cell:&Cell,c:&Column,table:&str)->anyhow::Result<()>{let location=format!("{table}.{}",c.name);match cell{Cell::Null=>ensure!(!c.required,"NULL required/primary key: {location}"),Cell::Text(raw)if c.kind=="TEXT"=>{ensure!(!raw.contains(&0),"NUL TEXT: {location}");std::str::from_utf8(raw).with_context(||format!("Invalid UTF8 TEXT: {location}"))?;},Cell::Integer(_)if c.kind=="BIGINT"=>{},Cell::Blob(_)if c.kind=="BYTEA"=>{},_=>bail!("Unrepresentable storage class: {location}")};Ok(())}
fn table_hash(table:&Table)->anyhow::Result<String>{let mut rows:Vec<_>=table.rows.iter().map(serde_json::to_vec).collect::<Result<_,_>>()?;rows.sort();let mut h=Sha256::new();for row in rows{h.update((row.len()as u64).to_be_bytes());h.update(row);}Ok(hex::encode(h.finalize()))}
fn preflight(bundle:&crate::storage::backup_inventory::ValidatedBundle)->anyhow::Result<NativeSnapshot<'_>> {
 ensure!(bundle.manifest.historical_composite_preservation_capture.is_none(),"Historical physical source requires a distinct qualified destination; generic Transfer fallback refused");
 bundle.fence()?;let manifest:serde_json::Value=serde_json::from_slice(&bundle.raw_manifest)?;ensure!(manifest["database"]["engine"]=="sqlite"&&matches!(manifest["database"]["applied_version"].as_i64(),Some(49|50|51|52|53|54|55|56|57)),"Authenticated SQLite49 through57 profile required");let file=bundle.open_owned("starlane-notes.db")?;let native=NativeDb::open(&file)?;ensure!(native.rows("PRAGMA encoding")?==vec![vec![Cell::Text(b"UTF-8".to_vec())]],"First transfer slice requires UTF8 SQLite encoding");let schema=native.rows("SELECT type,name,tbl_name,sql FROM sqlite_master ORDER BY type,name")?;let actual:std::collections::BTreeSet<_>=schema.iter().filter(|r|text(&r[0]).ok()==Some("table")).map(|r|text(&r[1]).map(str::to_owned)).collect::<Result<_,_>>()?;let source_profile=match manifest["database"]["applied_version"].as_i64(){Some(49)=>EngineCatalogueProfile::Historical49Pg3,Some(50)=>EngineCatalogueProfile::Registry50Pg4,Some(51)=>EngineCatalogueProfile::Capacity51Pg5,Some(52)=>EngineCatalogueProfile::Retention52Pg6,Some(53)=>EngineCatalogueProfile::Erasure53Pg7,Some(54)=>EngineCatalogueProfile::Publication54Pg8,Some(55)=>EngineCatalogueProfile::Audience55Pg9,Some(56)=>EngineCatalogueProfile::DraftTransfer56Pg10,Some(57)=>EngineCatalogueProfile::Discussion57Pg11,_=>bail!("Unknown authenticated source profile")};let mut tables=shape_for_profile(source_profile)?;let expected:std::collections::BTreeSet<_>=tables.keys().cloned().chain(std::iter::once("_sqlx_migrations".into())).collect();ensure!(actual==expected,"Unexpected source table set");ensure!(native.rows("PRAGMA integrity_check")?==vec![vec![Cell::Text(b"ok".to_vec())]],"Source integrity failed");ensure!(native.rows("PRAGMA foreign_key_check")?.is_empty(),"Source FK violations");
 let mut references=vec![];let mut total=0usize;
 for(n,t)in &mut tables{let info=native.rows(&format!("PRAGMA table_info({})",quoted(n)?))?;let cols:Vec<_>=info.iter().map(|r|text(&r[1]).map(str::to_owned)).collect::<Result<_,_>>()?;ensure!(cols==t.columns.iter().map(|c|c.name.clone()).collect::<Vec<_>>(),"Source column mismatch: {n}");let mut keys:Vec<_>=info.iter().filter_map(|r|if let Cell::Integer(order)=r[5]{if order>0{Some((order,text(&r[1]).map(str::to_owned)))}else{None}}else{None}).collect();keys.sort_by_key(|r|r.0);ensure!(keys.into_iter().map(|r|r.1).collect::<Result<Vec<_>,_>>()?==t.keys,"Source key mismatch: {n}");let projections=t.columns.iter().map(|c|quoted(&c.name)).collect::<Result<Vec<_>,_>>()?.join(",");t.rows=native.rows(&format!("SELECT {projections} FROM {}",quoted(n)?))?;let mut seen=std::collections::BTreeSet::new();
 for row in &t.rows{ensure!(row.len()==t.columns.len(),"Row width differs");for(cell,c)in row.iter().zip(&t.columns){validate_cell(cell,c,n)?;}let key:Vec<_>=t.keys.iter().map(|k|row[t.columns.iter().position(|c|c.name==*k).unwrap()].clone()).collect();ensure!(seen.insert(serde_json::to_vec(&key)?),"Duplicate target key: {n}");total=total.checked_add(serde_json::to_vec(row)?.len()).context("Logical size overflow")?;ensure!(total<=512*1024*1024,"Logical snapshot bound exceeded");
 if n=="documents"||n=="attachments"{let column=if n=="documents"{"content_path"}else{"storage_path"};if let Some(i)=t.columns.iter().position(|c|c.name==column){if !matches!(row[i],Cell::Null){let path=text(&row[i])?;ensure!(!Path::new(path).is_absolute()&&!path.split('/').any(|p|p.is_empty()||p==".."||p=="."),"Unsafe current file reference");ensure!(bundle.manifest.files.0.contains_key(path),"Uncaptured current file reference");references.push(path.to_owned());}}}
 }}
 let migrations=native.rows("SELECT version,description,installed_on,success,checksum,execution_time FROM _sqlx_migrations ORDER BY version")?;native.close()?;references.sort();references.dedup();bundle.fence()?;Ok(NativeSnapshot{profile:source_profile,bundle,_database:file,tables,schema_rows:schema,raw_sqlite_migrations:migrations,reference_paths:references})
}
impl NativeSnapshot<'_>{fn certificate(&self)->anyhow::Result<PreflightCertificate>{self.bundle.fence()?;Ok(PreflightCertificate{backup_id:self.bundle.manifest.backup_id.clone(),manifest_sha256:digest(&self.bundle.raw_manifest),sqlite_database_sha256:self.bundle.manifest.files.0["starlane-notes.db"].sha256.clone(),source_schema_sha256:digest(&serde_json::to_vec(&self.schema_rows)?),target_schema_baseline_sha256:digest(concat!(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0001_current_schema.sql")), include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0002_current_seed_data.sql")), include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0003_attachment_upload_receipts.sql")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0004_immutable_attachment_versions.sql")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0005_attachment_capacity_reservations.sql")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0006_attachment_erasure_outbox.sql")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0007_attachment_erasure_dispositions.sql")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0008_document_publication_history.sql")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0009_draft_asset_audiences.sql")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0010_draft_transfer_receipts.sql")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/migrations-postgres/0011_draft_discussions.sql"))).as_bytes()),table_hashes:self.tables.iter().map(|(n,t)|Ok((n.clone(),(t.rows.len(),table_hash(t)?)))).collect::<anyhow::Result<_>>()?,source_migrations_sha256:digest(&serde_json::to_vec(&self.raw_sqlite_migrations)?),checked_current_file_references:self.reference_paths.clone(),serving_allowed:false})}}
